<?php $title='Workout completed';$grouped=[];foreach($session['rows'] as $row)$grouped[$row['workout_exercise_id']][]=$row; ?>
<div class="mx-auto max-w-3xl"><div class="mb-6 text-center"><p class="text-6xl">✅</p><h1 class="mt-3 text-3xl font-black">Workout completed</h1><p class="mt-1 text-zinc-400"><?= e($session['session_type']) ?></p></div>
<?php if($achievements):?><section class="mb-6 rounded-2xl border border-violet-700/60 bg-violet-950/25 p-5"><p class="text-sm font-semibold text-violet-400">NEW ACHIEVEMENTS</p><div class="mt-3 grid gap-3 sm:grid-cols-2"><?php foreach($achievements as $achievement):?><div class="rounded-xl bg-zinc-900 p-3"><span class="text-2xl"><?= e($achievement['icon']) ?></span><strong class="ml-2"><?= e($achievement['name']) ?></strong><p class="mt-1 text-sm text-zinc-400"><?= e($achievement['description']) ?></p></div><?php endforeach;?></div></section><?php endif;?>
<div class="grid gap-3 sm:grid-cols-2"><?php foreach($grouped as $rows):$working=array_values(array_filter($rows,fn($row)=>$row['id']&&$row['set_type']==='working'));if(!$working)continue;usort($working,fn($a,$b)=>(float)$b['weight_kg']<=>(float)$a['weight_kg'] ?: (int)$b['repetitions']<=>(int)$a['repetitions']);$best=$working[0];$pr=max(array_column($working,'is_personal_record'));$mode=$rows[0]['equipment']==='Dumbbells'?($rows[0]['load_semantics']==='per_dumbbell'?'per dumbbell':'total'):null;?><a href="/exercises/<?= (int)$rows[0]['exercise_id'] ?>" class="card"><div class="flex justify-between gap-2"><strong><?= e($rows[0]['name']) ?></strong><?php if($pr):?><span class="text-emerald-400">🏆 PR</span><?php endif;?></div><p class="mt-2 text-xl font-black"><?= e(format_number($best['weight_kg'])) ?> kg × <?= (int)$best['repetitions'] ?></p><?php if($mode): ?><p class="text-xs text-zinc-500"><?= e($mode) ?></p><?php endif; ?></a><?php endforeach;?></div><div class="mt-6 flex flex-wrap justify-center gap-3"><a href="/" class="btn-primary">Back to dashboard</a><a href="/achievements" class="btn-stat">🏆 Achievements</a></div></div>
